class EvaluationFormReferenceController extends Controller { public function index(Request $request): JsonResponse { return ApiResponse::success(['forms'=>EvaluationFormVersion::with(['department:id,name_ar,name_en','course:id,code,name_ar,name_en'])->when(!$request->boolean('show_archived'), fn($q)=>$q->whereNull('archived_at'))->orderBy('form_code')->get(), 'items'=>EvaluationFormItem::when(!$request->boolean('show_archived'), fn($q)=>$q->whereNull('archived_at'))->orderBy('item_code')->get()]); } public function storeVersion(Request $r):JsonResponse{$d=$r->validate(['form_code'=>['required','string'],'name'=>['required','string'],'version'=>['required','string'],'department_id'=>['nullable','exists:departments,id'],'course_id'=>['nullable','exists:courses,id'],'evaluator_type'=>['nullable','string'],'evaluatee_type'=>['nullable','string'],'effective_from'=>['nullable','date'],'effective_until'=>['nullable','date'],'total_score'=>['nullable','numeric'],'status'=>['nullable','string'],'notes'=>['nullable','string']]);return ApiResponse::success(EvaluationFormVersion::create($d),'Version created.',[],201);} public function updateVersion(Request $r, EvaluationFormVersion $version):JsonResponse{$version->update($r->validate(['form_code'=>['sometimes','string'],'name'=>['sometimes','string'],'version'=>['sometimes','string'],'department_id'=>['nullable','exists:departments,id'],'course_id'=>['nullable','exists:courses,id'],'evaluator_type'=>['nullable','string'],'evaluatee_type'=>['nullable','string'],'effective_from'=>['nullable','date'],'effective_until'=>['nullable','date'],'total_score'=>['nullable','numeric'],'status'=>['nullable','string'],'notes'=>['nullable','string']]));return ApiResponse::success($version->fresh());} public function archiveVersion(EvaluationFormVersion $version):JsonResponse{$version->update(['archived_at'=>now()]);return ApiResponse::success($version->fresh(),'Record archived.');} public function storeItem(Request $r):JsonResponse{$d=$r->validate(['evaluation_form_version_id'=>['nullable','exists:evaluation_form_versions,id'],'item_code'=>['required','string'],'item_text'=>['required','string'],'domain'=>['nullable','string'],'rating_scale'=>['nullable','string'],'weight'=>['nullable','numeric'],'program_outcome_code'=>['nullable','string'],'applicable_courses'=>['nullable','string'],'notes'=>['nullable','string']]);return ApiResponse::success(EvaluationFormItem::create($d),'Item created.',[],201);} public function updateItem(Request $r, EvaluationFormItem $item):JsonResponse{$item->update($r->validate(['evaluation_form_version_id'=>['nullable','exists:evaluation_form_versions,id'],'item_code'=>['sometimes','string'],'item_text'=>['sometimes','string'],'domain'=>['nullable','string'],'rating_scale'=>['nullable','string'],'weight'=>['nullable','numeric'],'program_outcome_code'=>['nullable','string'],'applicable_courses'=>['nullable','string'],'notes'=>['nullable','string']]));return ApiResponse::success($item->fresh());} public function archiveItem(EvaluationFormItem $item):JsonResponse{$item->update(['archived_at'=>now()]);return ApiResponse::success($item->fresh(),'Record archived.');} }
